      }
    },
    {
      "id": "simulateWeather",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Simulate Bellevue Weather"
      },
      "inputs": {
        "script": "var scenarios = [\n  { condition: \"Sunny\", tempF: 72, humidityPct: 35, windMph: 5, precipitationIn: 0.0 },\n  { condition: \"Partly Cloudy\", tempF: 65, humidityPct: 55, windMph: 10, precipitationIn: 0.0 },\n  { condition: \"Overcast\", tempF: 58, humidityPct: 70, windMph: 12, precipitationIn: 0.0 },\n  { condition: \"Light Rain\", tempF: 52, humidityPct: 85, windMph: 15, precipitationIn: 0.25 },\n  { condition: \"Heavy Rain\", tempF: 47, humidityPct: 95, windMph: 22, precipitationIn: 1.1 },\n  { condition: \"Thunderstorms\", tempF: 55, humidityPct: 90, windMph: 35, precipitationIn: 0.8 },\n  { condition: \"Fog\", tempF: 50, humidityPct: 98, windMph: 3, precipitationIn: 0.0 },\n  { condition: \"Clear and Cool\", tempF: 60, humidityPct: 45, windMph: 8, precipitationIn: 0.0 }\n];\nvar idx = Math.floor(Math.random() * scenarios.length);\nvar w = scenarios[idx];\nreturn { location: \"Bellevue, WA\", condition: w.condition, tempF: w.tempF, humidityPct: w.humidityPct, windMph: w.windMph, precipitationIn: w.precipitationIn };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Simulated weather data for Bellevue, WA",
          "source": "=result.response",
          "var": "output"
        }
      }
    },
    {
      "id": "evaluateWeather",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Evaluate: Is It a Nice Day?"
      },
      "inputs": {
        "script": "var w = $vars.simulateWeather.output;\nvar reasons = [];\nif (w.tempF < 55) { reasons.push(\"Too cold (\" + w.tempF + \"\\u00b0F)\"); }\nif (w.tempF > 85) { reasons.push(\"Too hot (\" + w.tempF + \"\\u00b0F)\"); }\nif (w.precipitationIn > 0.05) { reasons.push(\"Too much rain (\" + w.precipitationIn + \"\\\")\"); }\nif (w.windMph > 20) { reasons.push(\"Too windy (\" + w.windMph + \" mph)\"); }\nvar badConditions = [\"Heavy Rain\", \"Thunderstorms\", \"Fog\"];\nif (badConditions.indexOf(w.condition) !== -1) { reasons.push(\"Unpleasant condition: \" + w.condition); }\nvar isNice = reasons.length === 0;\nvar verdict = isNice ? \"\\u2600\\ufe0f It's a NICE DAY! Get outside!\" : \"\\ud83c\\udf27\\ufe0f NOT a nice day. Stay cozy indoors.\";\nreturn { isNice: isNice, verdict: verdict, reasons: reasons };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Day evaluation result",
          "source": "=result.response",
          "var": "output"
        }
      }
    },
    {
      "id": "buildReport",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Build Weather Report"
      },
      "inputs": {
        "script": "var w = $vars.simulateWeather.output;\nvar e = $vars.evaluateWeather.output;\nvar sep = \"==================================================\";\nvar lines = [\n  sep,\n  \"  Bellevue Weather Check — \" + w.location,\n  sep,\n  \"  Condition    : \" + w.condition,\n  \"  Temperature  : \" + w.tempF + \"\\u00b0F\",\n  \"  Humidity     : \" + w.humidityPct + \"%\",\n  \"  Wind         : \" + w.windMph + \" mph\",\n  \"  Precipitation: \" + w.precipitationIn + \"\\\"\",\n  \"--------------------------------------------------\",\n  \"  \" + e.verdict\n];\nif (!e.isNice && e.reasons.length > 0) {\n  lines.push(\"\");\n  lines.push(\"  Reasons:\");\n  for (var i = 0; i < e.reasons.length; i++) {\n    lines.push(\"    \\u2022 \" + e.reasons[i]);\n  }\n}\nlines.push(sep);\nreturn { report: lines.join(\"\\n\"), isNiceDay: e.isNice, verdict: e.verdict };"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Formatted weather report",
          "source": "=result.response",
          "var": "output"
        }
      }
    },
    {
      "id": "end",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Done"
      },
      "inputs": {},
      "outputs": {
        "report": {
          "source": "=js:$vars.buildReport.output.report"
        },
        "isNiceDay": {
          "source": "=js:$vars.buildReport.output.isNiceDay"
        },
        "verdict": {
          "source": "=js:$vars.buildReport.output.verdict"
        }
      }
    }
  ],
  "edges": [
    {
      "id": "edge-start-simulate",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "simulateWeather",
      "targetPort": "input"
    },
