inputs.script:
var scenarios = [
  { condition: "Sunny", tempF: 72, humidityPct: 35, windMph: 5, precipitationIn: 0.0 },
  { condition: "Partly Cloudy", tempF: 65, humidityPct: 55, windMph: 10, precipitationIn: 0.0 },
  { condition: "Overcast", tempF: 58, humidityPct: 70, windMph: 12, precipitationIn: 0.0 },
  { condition: "Light Rain", tempF: 52, humidityPct: 85, windMph: 15, precipitationIn: 0.25 },
  { condition: "Heavy Rain", tempF: 47, humidityPct: 95, windMph: 22, precipitationIn: 1.1 },
  { condition: "Thunderstorms", tempF: 55, humidityPct: 90, windMph: 35, precipitationIn: 0.8 },
  { condition: "Fog", tempF: 50, humidityPct: 98, windMph: 3, precipitationIn: 0.0 },
  { condition: "Clear and Cool", tempF: 60, humidityPct: 45, windMph: 8, precipitationIn: 0.0 }
];
var idx = Math.floor(Math.random() * scenarios.length);
var w = scenarios[idx];
return { location: "Bellevue, WA", condition: w.condition, tempF: w.tempF, humidityPct: w.humidityPct, windMph: w.windMph, precipitationIn: w.precipitationIn };

var w = $vars.simulateWeather.output;
var reasons = [];
if (w.tempF < 55) { reasons.push("Too cold (" + w.tempF + "\u00b0F)"); }
if (w.tempF > 85) { reasons.push("Too hot (" + w.tempF + "\u00b0F)"); }
if (w.precipitationIn > 0.05) { reasons.push("Too much rain (" + w.precipitationIn + "\")"); }
if (w.windMph > 20) { reasons.push("Too windy (" + w.windMph + " mph)"); }
var badConditions = ["Heavy Rain", "Thunderstorms", "Fog"];
if (badConditions.indexOf(w.condition) !== -1) { reasons.push("Unpleasant condition: " + w.condition); }
var isNice = reasons.length === 0;
var verdict = isNice ? "\u2600\ufe0f It's a NICE DAY! Get outside!" : "\ud83c\udf27\ufe0f NOT a nice day. Stay cozy indoors.";
return { isNice: isNice, verdict: verdict, reasons: reasons };

var w = $vars.simulateWeather.output;
var e = $vars.evaluateWeather.output;
var sep = "==================================================";
var lines = [
  sep,
  "  Bellevue Weather Check — " + w.location,
  sep,
  "  Condition    : " + w.condition,
  "  Temperature  : " + w.tempF + "\u00b0F",
  "  Humidity     : " + w.humidityPct + "%",
  "  Wind         : " + w.windMph + " mph",
  "  Precipitation: " + w.precipitationIn + "\"",
  "--------------------------------------------------",
  "  " + e.verdict
];
if (!e.isNice && e.reasons.length > 0) {
  lines.push("");
  lines.push("  Reasons:");
  for (var i = 0; i < e.reasons.length; i++) {
    lines.push("    \u2022 " + e.reasons[i]);
  }
}
lines.push(sep);
return { report: lines.join("\n"), isNiceDay: e.isNice, verdict: e.verdict };

